-- ----------------------------
-- Function structure for generate_customer_code
-- ----------------------------
DROP FUNCTION IF EXISTS "public"."generate_customer_code"();
CREATE FUNCTION "public"."generate_customer_code"()
  RETURNS "pg_catalog"."trigger" AS $BODY$
DECLARE
    year_part TEXT;
    sequence_part TEXT;
BEGIN
    year_part := TO_CHAR(NOW(), 'YYYY');
    sequence_part := LPAD(CAST((
        SELECT COALESCE(MAX(CAST(SUBSTRING(customer_code FROM 10) AS INTEGER)), 0) + 1
        FROM m_customer
        WHERE customer_code LIKE 'CUST-' || year_part || '-%'
    ) AS TEXT), 4, '0');
    NEW.customer_code := 'CUST-' || year_part || '-' || sequence_part;
    RETURN NEW;
END;
$BODY$
  LANGUAGE plpgsql VOLATILE
  COST 100;

-- ----------------------------
-- Function structure for generate_job_no
-- ----------------------------
DROP FUNCTION IF EXISTS "public"."generate_job_no"();
CREATE FUNCTION "public"."generate_job_no"()
  RETURNS "pg_catalog"."trigger" AS $BODY$
DECLARE
    year_part TEXT;
    sequence_part TEXT;
BEGIN
    year_part := TO_CHAR(NOW(), 'YYYY');
    sequence_part := LPAD(CAST((
        SELECT COALESCE(MAX(CAST(SUBSTRING(job_no FROM 9) AS INTEGER)), 0) + 1
        FROM t_job
        WHERE job_no LIKE 'JOB-' || year_part || '-%'
    ) AS TEXT), 4, '0');
    NEW.job_no := 'JOB-' || year_part || '-' || sequence_part;
    RETURN NEW;
END;
$BODY$
  LANGUAGE plpgsql VOLATILE
  COST 100;

-- ----------------------------
-- Function structure for generate_po_no
-- ----------------------------
DROP FUNCTION IF EXISTS "public"."generate_po_no"();
CREATE FUNCTION "public"."generate_po_no"()
  RETURNS "pg_catalog"."trigger" AS $BODY$
DECLARE
    year_part TEXT;
    sequence_part TEXT;
BEGIN
    year_part := TO_CHAR(NOW(), 'YYYY');
    sequence_part := LPAD(CAST((
        SELECT COALESCE(MAX(CAST(SUBSTRING(po_no FROM 6) AS INTEGER)), 0) + 1
        FROM t_po_header
        WHERE po_no LIKE 'PO-' || year_part || '-%'
    ) AS TEXT), 4, '0');
    NEW.po_no := 'PO-' || year_part || '-' || sequence_part;
    RETURN NEW;
END;
$BODY$
  LANGUAGE plpgsql VOLATILE
  COST 100;

-- ----------------------------
-- Function structure for generate_quotation_no
-- ----------------------------
DROP FUNCTION IF EXISTS "public"."generate_quotation_no"();
CREATE FUNCTION "public"."generate_quotation_no"()
  RETURNS "pg_catalog"."trigger" AS $BODY$
DECLARE
    year_part TEXT;
    sequence_part TEXT;
BEGIN
    year_part := TO_CHAR(NOW(), 'YYYY');
    sequence_part := LPAD(CAST((
        SELECT COALESCE(MAX(CAST(SUBSTRING(quotation_no FROM 8) AS INTEGER)), 0) + 1
        FROM t_quotation
        WHERE quotation_no LIKE 'QT-' || year_part || '-%'
    ) AS TEXT), 4, '0');
    NEW.quotation_no := 'QT-' || year_part || '-' || sequence_part;
    RETURN NEW;
END;
$BODY$
  LANGUAGE plpgsql VOLATILE
  COST 100;

